insert into assessor_private.orientation_units
  (chapter_key,curriculum_version,orientation_version,title,guide,lessons,cases,passing_count)
values (
  'chapter-2','2026-09-28.1','2026-09-29.2',
  '{"fil":"Oryentasyon sa pagmamarka ng first responder","en":"First responder scoring orientation"}'::jsonb,
  '[{"fil":"Gamitin ang eksaktong Chapter II indicator. Ihiwalay ang aktuwal na nakita sa hula, attendance, at test score.","en":"Use the exact Chapter II indicator. Separate observed actions from assumptions, attendance, and test scores."},{"fil":"Sa kunwaring kaso, markahan lamang ang ipinakitang gawain. Ang Kaya na ay tama at kusa; Kailangan pa ng practice ay nangangailangan ng prompt o pag-uulit; Hindi pa ay hindi naipakita ang mahalagang hakbang.","en":"In a simulated case, rate only the demonstrated action. Kaya na is correct and independent; Kailangan pa ng practice needs a prompt or repeat; Hindi pa misses the essential action."},{"fil":"Sa IPC at first aid, unahin ang kaligtasan. Itigil ang hindi ligtas na gawain, tumawag sa kumpirmadong contact, at sundin ang lokal na protocol. Huwag magbigay ng diagnosis, gamot, o hindi awtorisadong paggamot.","en":"In IPC and first aid, put safety first. Stop unsafe work, call the confirmed contact, and follow local protocol. Do not diagnose, prescribe, or perform unauthorized treatment."}]'::jsonb,
  '[{"id":"eligibility","title":{"fil":"1. Suriin ang kahandaan","en":"1. Check readiness"},"body":[{"fil":"Bago mag-assess, tiyaking natapos ng BHW ang kinakailangang aralin at pagsusulit ng kaugnay na subchapter. Hindi sapat ang attendance o progress bar.","en":"Before assessment, confirm the BHW completed the related subchapter''s required lessons and tests. Attendance or a progress bar is insufficient."},{"fil":"Suriin ang sarili mong aktibong Chapter II qualification, assigned area, at kasalukuyang assignment. Ang Chapter I qualification ay hindi kapalit ng Chapter II.","en":"Check your active Chapter II qualification, assigned area, and current assignment. A Chapter I qualification does not substitute for Chapter II."}]},{"id":"evidence","title":{"fil":"2. Itala ang aktuwal na ebidensya","en":"2. Record observed evidence"},"body":[{"fil":"Isulat kung ano ang sinabi at ginawa, kung may prompt, ang oras at setting. Huwag gawing diagnosis o pangako ang obserbasyon.","en":"Record what was said and done, whether a prompt was given, and the time and setting. Do not turn an observation into a diagnosis or promise."},{"fil":"Para sa simulation, sabihin na kunwari lamang ang kaso. Huwag gumamit ng tunay na pasyente o personal na detalye bilang practice case.","en":"Label a simulation as fictional. Do not use a real patient or personal details as a practice case."}]},{"id":"anchors","title":{"fil":"3. Ihambing sa rating anchor","en":"3. Compare with the rating anchor"},"body":[{"fil":"Basahin ang observable at tatlong anchor ng tiyak na indicator. Ang mahinahong pakikinig na may buod lamang matapos ang prompt ay Kailangan pa ng practice.","en":"Read the observable behavior and three anchors for the specific indicator. Calm listening with a summary only after prompting is Kailangan pa ng practice."},{"fil":"Huwag magbigay ng antas kapag hindi naobserbahan ang gawain. Magtakda ng pagkakataong magpakita muli at panatilihin ang naunang record.","en":"Do not assign a level when the task was not observed. Arrange another chance to demonstrate and retain the earlier record."}]},{"id":"safety","title":{"fil":"4. Unahin ang kaligtasan at saklaw","en":"4. Put safety and scope first"},"body":[{"fil":"Sa IPC, hindi sapat ang gloves o handrub kapag kailangang hugasan ang may dumi na kamay. Obserbahan ang tamang paraan at sundin ang BHS protocol.","en":"In IPC, gloves or handrub do not replace washing visibly dirty hands. Observe the right method and follow the BHS protocol."},{"fil":"Sa first aid simulation, manatili sa ligtas na lugar, humingi ng tulong, at iulat ang nakita at lokasyon. Hindi dapat pumasok sa panganib upang kumpletuhin ang checklist.","en":"In a first aid simulation, stay safe, activate help, and report observations and location. Do not enter a hazard to complete a checklist."}]},{"id":"feedback","title":{"fil":"5. Feedback at muling pagtatasa","en":"5. Feedback and reassessment"},"body":[{"fil":"Ibahagi nang pribado ang tiyak na ebidensya, rating anchor, at isang practice step. Pakinggan ang pagwawasto sa factual record.","en":"Privately explain the exact evidence, rating anchor, and one practice step. Accept corrections to the factual record."},{"fil":"Sa susunod na pagtatangka, gumawa ng bagong obserbasyon. Huwag burahin ang una o ilipat ang marka sa bagong rubric nang walang pagsusuri.","en":"On a later attempt, record a new observation. Do not erase the first or transfer a rating to a revised rubric without review."}]},{"id":"final-review","title":{"fil":"6. Suriin ang buong chapter","en":"6. Review the whole chapter"},"body":[{"fil":"Suriin ang bawat kinakailangang indicator sa pitong subchapter. Ang mataas na average ay hindi kapalit ng kulang o hindi ligtas na ebidensya.","en":"Review every required indicator across the seven subchapters. A high average does not replace missing or unsafe evidence."},{"fil":"Ibigay ang malinaw na dahilan at susunod na hakbang. Ang orientation exercise na ito ay pagsasanay sa pagmamarka, hindi aktuwal na BHW assessment o certificate.","en":"Give a clear reason and next step. This orientation exercise trains scoring; it is not an actual BHW assessment or certificate."}]}]'::jsonb,
  '[{"id":"listening-prompted","indicator":"chapter-2:01-difficult-situations:indicator-2","case":{"fil":"Mahinahon na pinakinggan ng BHW si Liza ngunit hindi niya pinasuri ang buod. Matapos ang paalala ng trainer, ibinuod niya ang dalawang pagbisita at malabong contact at humingi ng pagwawasto.","en":"The BHW listens calmly to Liza but does not check a summary. After the trainer prompts them, they summarize the two visits and unclear contact and invite correction."},"correct":"kailangan_practice","reason":{"fil":"Kailangan ng prompt upang maipakumpirma ang buod, ayon sa Kailangan pa ng practice anchor.","en":"A prompt was needed to check the summary, matching the Kailangan pa ng practice anchor."}},{"id":"privacy-support","indicator":"chapter-2:02-quality-service:indicator-2","case":{"fil":"Inalok ng BHW si Alex ng pribadong lugar, tinanong kung anong tulong ang nais niya, at nagpaliwanag nang walang bansag o sapilitang pagsama ng iba. Ginawa niya ito nang walang paalala.","en":"The BHW offers Alex a private space, asks what help he prefers, and explains without labels or involving anyone else against his wishes. No prompt is needed."},"correct":"kaya_na","reason":{"fil":"Pribado at ayon sa hiling ni Alex ang tulong, nang walang prompt: Kaya na.","en":"Support is private and matched to Alex’s preference without prompting: Kaya na."}},{"id":"dirty-hands-rub","indicator":"chapter-2:03-infection-control:indicator-3","critical":true,"case":{"fil":"Sa simulation, kitang may dumi ang mga kamay ng BHW. Gumamit lamang siya ng handrub at pinunasan ito bago matuyo, kahit may lugar para maghugas.","en":"In the simulation, the BHW’s hands are visibly dirty. They use only handrub and wipe it off before it dries, though handwashing is available."},"correct":"hindi_pa","reason":{"fil":"Ang handrub sa may dumi na kamay at pagpahid bago matuyo ay Hindi pa anchor. Ihinto at itama ang paraan.","en":"Using handrub on visibly dirty hands and wiping it off before dry matches Hindi pa. Stop and correct the method."}},{"id":"scene-safety","indicator":"chapter-2:04-first-aid:indicator-1","critical":true,"case":{"fil":"Sa kunwaring aksidente sa kalsada, pumasok ang BHW sa simulated na trapiko upang magtanong muna ng buong kuwento. Hindi siya nagtalaga ng tatawag sa kumpirmadong emergency contact.","en":"In a simulated roadside incident, the BHW steps into simulated traffic to ask for the full story first. They do not assign anyone to call the confirmed emergency contact."},"correct":"hindi_pa","reason":{"fil":"Pumasok sa panganib at inantala ang tawag: Hindi pa. Manatili sa ligtas na lugar at humingi ng tulong.","en":"Entering the hazard and delaying the call is Hindi pa. Stay safe and activate help."}},{"id":"handover-prompted","indicator":"chapter-2:04-first-aid:indicator-18","case":{"fil":"Factual ang handover ng BHW tungkol sa nakita at ginawa, ngunit nakalimutan niya ang oras at hindi hiniling na kumpirmahin ang susunod na hakbang hanggang paalalahanan siya.","en":"The BHW gives a factual handover of observations and actions but omits the times and does not ask the receiver to confirm the next step until prompted."},"correct":"kailangan_practice","reason":{"fil":"Nailahad ang facts ngunit kailangan ng prompt para sa oras at kumpirmasyon: Kailangan pa ng practice.","en":"The facts are given, but times and confirmation require a prompt: Kailangan pa ng practice."}},{"id":"plant-card-check","indicator":"chapter-2:05-medicinal-plants:indicator-1","case":{"fil":"Sa dalawang fictional plant card, minarkahan ng BHW ang botanical name, bahagi, kulang na kumpirmasyon, at health professional na kokonsultahin. Hindi siya nagbigay ng dose o pumili batay sa larawan. Walang prompt.","en":"Using two fictional plant cards, the BHW marks the botanical name, plant part, missing confirmation, and health professional to consult. They give no dose and do not identify by picture. No prompt is needed."},"correct":"kaya_na","reason":{"fil":"Kumpleto ang card comparison at konsultasyon nang walang prompt: Kaya na.","en":"The card comparison and consultation are complete without prompting: Kaya na."}},{"id":"chat-only-invite","indicator":"chapter-2:06-community-mobilization:indicator-2","case":{"fil":"Chat message lamang ang plano ng BHW para sa tatlong grupong may magkakaibang hadlang. Sinabi niyang kailangang dumalo upang makatanggap ng serbisyo.","en":"The BHW plans only a chat message for three groups with different barriers and says attendance is required to receive services."},"correct":"hindi_pa","reason":{"fil":"Chat lamang at ginawang kondisyon sa serbisyo ang pagdalo: Hindi pa.","en":"A chat-only approach and conditioning services on attendance match Hindi pa."}},{"id":"advisory-verified","indicator":"chapter-2:07-disaster-preparedness:indicator-2","case":{"fil":"Sa fictional advisory, sinabi ng BHW ang source at oras, inihiwalay ang kumpirmadong hakbang sa rutang hinihintay pang kumpirmahin, at tinukoy kung sino ang tatawagan. Walang prompt.","en":"For a fictional advisory, the BHW states its source and time, separates the confirmed action from a route still awaiting confirmation, and names whom to call. No prompt is needed."},"correct":"kaya_na","reason":{"fil":"Tugma ang source, oras, kumpirmadong aksiyon at contact sa Kaya na anchor.","en":"Source, time, confirmed action, and verification contact meet the Kaya na anchor."}}]'::jsonb,
  7
);

